# ---------------- Database ----------------
def db():
    con=sqlite3.connect(DB_FILE,timeout=10)
    con.execute('PRAGMA journal_mode=WAL')
    return con

def init_db():
    con=db(); cur=con.cursor()
    cur.execute('''CREATE TABLE IF NOT EXISTS quiz_attempts(
      id INTEGER PRIMARY KEY AUTOINCREMENT, player TEXT NOT NULL, category TEXT NOT NULL,
      mode TEXT NOT NULL, score INTEGER NOT NULL, total INTEGER NOT NULL, percentage REAL NOT NULL,
      correct INTEGER NOT NULL DEFAULT 0, fastest REAL NOT NULL DEFAULT 0, avg_time REAL NOT NULL DEFAULT 0,
      played_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)''')
    cur.execute('''CREATE TABLE IF NOT EXISTS player_stats(
      player TEXT PRIMARY KEY, games INTEGER NOT NULL DEFAULT 0, correct INTEGER NOT NULL DEFAULT 0,
      answered INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0,
      draws INTEGER NOT NULL DEFAULT 0, fastest REAL NOT NULL DEFAULT 0, total_time REAL NOT NULL DEFAULT 0,
      ranked_points INTEGER NOT NULL DEFAULT 0, last_played TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)''')
    cur.execute('''CREATE TABLE IF NOT EXISTS achievements(
      player TEXT NOT NULL, achievement TEXT NOT NULL, earned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      PRIMARY KEY(player,achievement))''')
    cur.execute('''CREATE TABLE IF NOT EXISTS multiplayer_matches(
      id INTEGER PRIMARY KEY AUTOINCREMENT, room_code TEXT NOT NULL, player1 TEXT NOT NULL, player2 TEXT NOT NULL,
      category TEXT NOT NULL, mode TEXT NOT NULL, score1 INTEGER NOT NULL, score2 INTEGER NOT NULL,
      winner TEXT NOT NULL, played_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)''')
    cur.execute('''CREATE TABLE IF NOT EXISTS question_history(
      id INTEGER PRIMARY KEY AUTOINCREMENT, player TEXT NOT NULL, category TEXT NOT NULL, mode TEXT NOT NULL,
      question TEXT NOT NULL, options TEXT NOT NULL, user_answer TEXT, correct_answer TEXT NOT NULL, was_correct INTEGER NOT NULL,
      played_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)''')
    con.commit(); con.close()

def ensure_player(player):
    con=db(); con.execute('INSERT OR IGNORE INTO player_stats(player) VALUES(?)',(player,)); con.commit(); con.close()

def update_stats(player, correct, answered, total_time, fastest, win=0, loss=0, draw=0, ranked_delta=0):
    ensure_player(player); con=db()
    con.execute('''UPDATE player_stats SET games=games+1,correct=correct+?,answered=answered+?,total_time=total_time+?,
        fastest=CASE WHEN fastest=0 OR (? > 0 AND ? < fastest) THEN ? ELSE fastest END,
        wins=wins+?,losses=losses+?,draws=draws+?,ranked_points=ranked_points+?,last_played=CURRENT_TIMESTAMP WHERE player=?''',
        (correct,answered,total_time,fastest,fastest,fastest,win,loss,draw,ranked_delta,player))
    con.commit(); con.close()

def save_question_history(player,category,mode,questions,answers):
    con=db()
    for i,q in enumerate(questions):
        ua=answers[i] if i<len(answers) else None
        con.execute('INSERT INTO question_history(player,category,mode,question,options,user_answer,correct_answer,was_correct) VALUES(?,?,?,?,?,?,?,?)',
            (player,category,mode,q['question'],json.dumps(q['options'],ensure_ascii=False),ua,q['answer'],int(ua==q['answer'])))
    con.commit(); con.close()

def save_attempt(player,category,mode,score,total,correct=None,times=None):
    correct=score if correct is None else correct; times=times or []
    fastest=min(times) if times else 0; avg=sum(times)/len(times) if times else 0
    con=db(); con.execute('INSERT INTO quiz_attempts(player,category,mode,score,total,percentage,correct,fastest,avg_time) VALUES(?,?,?,?,?,?,?,?,?)',
        (player,category,mode,score,total,(score/total*100 if total else 0),correct,fastest,avg)); con.commit(); con.close()
    update_stats(player,correct,len(times),sum(times),fastest)
    check_achievements(player)

def history(limit=100):
    con=db(); rows=con.execute('SELECT player,category,mode,score,total,percentage,fastest,avg_time,played_at FROM quiz_attempts ORDER BY id DESC LIMIT ?',(limit,)).fetchall(); con.close()
    return [dict(player=r[0],category=r[1],mode=r[2],score=r[3],total=r[4],percentage=round(r[5],1),fastest=round(r[6],2),avg_time=round(r[7],2),played_at=r[8]) for r in rows]

def leaderboard(limit=50):
    con=db(); rows=con.execute('SELECT player,ranked_points,wins,losses,draws,correct,answered FROM player_stats WHERE ranked_points>0 ORDER BY ranked_points DESC,wins DESC,correct DESC LIMIT ?',(limit,)).fetchall(); con.close()
    return [dict(rank=i+1,player=r[0],points=r[1],wins=r[2],losses=r[3],draws=r[4],correct=r[5],answered=r[6],level=level_for(dict(correct=r[5],wins=r[2],accuracy=(r[5]/r[6]*100 if r[6] else 0),fastest=0,games=0)),title=title_for(dict(correct=r[5],wins=r[2],accuracy=(r[5]/r[6]*100 if r[6] else 0),fastest=0,games=0,answered=r[6]))) for i,r in enumerate(rows)]

def stats_for(player):
    con=db(); r=con.execute('SELECT player,games,correct,answered,wins,losses,draws,fastest,total_time,ranked_points FROM player_stats WHERE player=?',(player,)).fetchone(); ach=con.execute('SELECT achievement,earned_at FROM achievements WHERE player=? ORDER BY earned_at',(player,)).fetchall(); con.close()
    if not r: return dict(player=player,games=0,correct=0,answered=0,accuracy=0,wins=0,losses=0,draws=0,fastest=0,avg_time=0,ranked_points=0,achievements=[])
    stats=dict(player=r[0],games=r[1],correct=r[2],answered=r[3],accuracy=round(r[2]/r[3]*100,1) if r[3] else 0,wins=r[4],losses=r[5],draws=r[6],fastest=round(r[7],2),avg_time=round(r[8]/r[3],2) if r[3] else 0,ranked_points=r[9],achievements=[a[0] for a in ach]); stats['level']=level_for(stats); stats['title']=title_for(stats); return stats


def level_for(stats): return 1 + (stats['correct'] + stats['wins']*5)//20
def title_for(stats):
    if stats['wins']>=20:return 'Ranked Champion'
    if stats['accuracy']>=90 and stats['answered']>=50:return 'Knowledge Master'
    if stats['fastest'] and stats['fastest']<=2:return 'Speed Demon'
    if stats['wins']>=5:return 'Quiz Warrior'
    if stats['games']>=10:return 'Quiz Explorer'
    return 'Knowledge Seeker'

def check_achievements(player):
    s=stats_for(player); earned=[]
    if s['games']>=1: earned.append('First Quiz')
    if s['wins']>=1: earned.append('First Victory')
    if s['accuracy']>=90 and s['answered']>=20: earned.append('Sharp Mind')
    if s['fastest'] and s['fastest']<=2: earned.append('Speed Demon')
    if s['ranked_points']>=20: earned.append('Ranked Contender')
    con=db()
    for a in earned: con.execute('INSERT OR IGNORE INTO achievements(player,achievement) VALUES(?,?)',(player,a))
    con.commit(); con.close()

# ---------------- Question quality engine ----------------
STOP=set('the a an and or of to in on for with from is are was were be been being what which who whom whose how why does do did can could would should this that these those into by as at it its their his her your you i we they he she'.split())
def norm(x): return re.sub(r'[^a-z0-9 ]',' ',str(x).lower())
def tokens(x): return {t for t in norm(x).split() if t not in STOP and len(t)>2}
def shape(x):
    s=str(x).strip(); n=norm(s)
    if re.search(r'[=+*/^√π²³∑∫]|\d',s) and (re.search(r'[+*/^=]|\d',s)) and len(s)<45: return 'formula'
    if re.fullmatch(r'[-+]?\d+(?:\.\d+)?(?:%|°)?',s): return 'number'
    if re.search(r'\b\d{4}\b',s) and len(s)<20: return 'year'
    if ',' in s or ' and ' in s.lower(): return 'list'
    if len(s.split())<=4: return 'short'
    return 'phrase'
def cue(q):
    n=norm(q)
    for c in ('synonym','opposite','meaning','describe','definition','year','where','when','who','which','what','how many','how much'):
        if c in n: return c
    return ''
def family(q):
    n=norm(q)
    groups=[
      ('vocab_word',('synonym','antonym','opposite','word means','what does','meaning of','closest meaning','describe','“','”')),
      ('morphology',('plural of','prefix','suffix','apostrophe')),
      ('literary_device',('literary device','figure of speech','poetry device','rhetorical device')),
      ('poetry',('meter in poetry','poetic','stanza','rhyme','iamb','sonnet')),
      ('grammar',('part of speech','verb tense','grammatical','sentence','clause','pronoun','adjective','adverb')),
      ('formula',('formula','equation','calculate','solve for','volume of','area of','probability of')),
      ('unit',('si unit','unit of','measured in')),
      ('chem_quantity',('molar','mole','ph value','ph at','avogadro','oxidation state','electron','atomic number','mass number')),
      ('geography_ocean',('largest ocean','deepest ocean','ocean trench','ocean','sea')),
      ('geography_size',('largest continent','largest country','smallest country','highest mountain')),
      ('currency',('currency of','money used in','legal tender')),
      ('text',('text','book','code','document')),
      ('definition',('definition','what is','what are')),
      ('person',('philosopher','ruler','president','emperor','queen','king','leader','explorer','historian','painter','who ','who was','who is','who led','who wrote','who painted','who directed','who founded','who became','which ruler','which philosopher')),
      ('place',('where ','which city','which country','which place','capital','civilization','empire')),
      ('year',('which year','what year','when did','when was','when were')),
      ('battle',('which battle','which conflict','which war','which revolution','which uprising','which movement','which massacre')),
      ('organization',('which organization','which treaty','which alliance','which plan','which agreement','which document','which act')),
      ('game_company',('which company developed','which company published','which developer','who developed','who published')),
      ('game_type',('what type of game','what genre')),
      ('game_rule',('chess piece','chessboard','dlc mean','downloadable content','console','handheld')),
      ('movie_director',('who directed','which director')),
      ('movie_feature',('which film features','which movie features','which series features','which franchise features')),
      ('cartoon_feature',('which cartoon features','which cartoon follows','which cartoon is','which animated series')),
      ('number',('how many','how much','how long','how old')),
      ('list',('which of these','which three','name three','list three')),
    ]
    for name,terms in groups:
        if any(t in n for t in terms): return name
    return cue(q) or 'general'

def compatible_answer(q,a):
    n=norm(q); s=str(a).strip()
    if 'plural of' in n: return bool(re.fullmatch(r'[A-Za-z][A-Za-z’\-]*(?:es|s|ae|i|ren|ice|geese|oxen|indices|criteria|phenomena)?',s))
    if 'prefix' in n or 'suffix' in n: return len(s.split())<=4
    if 'chessboard' in n: return bool(re.fullmatch(r'\d+',s))
    if 'largest ocean' in n: return s.lower() in {'pacific ocean','atlantic ocean','indian ocean','southern ocean','arctic ocean'}
    if 'ocean trench' in n: return 'trench' in s.lower() or s.lower() in {'mariana trench','tonga trench','kermadec trench','philippine trench'}
    if 'currency of' in n or 'currency' in n: return len(s.split())<=4 and not any(w in s.lower() for w in ('tokyo','skin','river','mountain'))
    if 'largest continent' in n: return s.lower() in {'asia','africa','north america','south america','antarctica','europe','australia'}
    if 'largest country' in n or 'smallest country' in n: return len(s.split())<=4
    if 'which battle' in n: return s.lower() in {'waterloo','saratoga','hastings','gettysburg','stalingrad','verdun','trafalgar','marathon','thermopylae','leipzig'} or 'battle' in s.lower()
    return True
def similarity(q1,a1,q2,a2):
    t1,t2=tokens(q1),tokens(q2); inter=len(t1&t2); union=max(1,len(t1|t2)); j=inter/union
    sh=1 if shape(a1)==shape(a2) else 0
    cu=1 if cue(q1)==cue(q2) else 0
    fam=1 if family(q1)==family(q2) else 0
    wa=max(1,len(str(a1).split())); wb=max(1,len(str(a2).split())); length=max(0,1-abs(wa-wb)/max(wa,wb))
    chars=max(0,1-abs(len(str(a1))-len(str(a2)))/max(len(str(a1)),len(str(a2))))
    return j*8+sh*4+cu*2+fam*8+length*3+chars*1.5

def giveaway(q,a):
    aq=tokens(a); qq=tokens(q)
    if not aq:return False
    if len(aq)==1 and next(iter(aq)) in qq:return True
    words=norm(a).split()
    if len(words)>=2 and all(w in norm(q).split() for w in words): return True
    return False

def clean_rows(category):
    rows=QUESTION_DATA[category]; out=[]; seen=set()
    for q,a in rows:
        key=norm(q)
        if not q or not a or key in seen: continue
        if giveaway(q,a): continue
        seen.add(key); out.append([q,a])
    return out

def topic_pool(q,a):
    n=norm(q)
    if 'largest ocean' in n: return ['Atlantic Ocean','Indian Ocean','Southern Ocean','Arctic Ocean']
    if 'ocean trench' in n: return ['Tonga Trench','Kermadec Trench','Philippine Trench','Japan Trench']
    if 'largest continent' in n: return ['Africa','Europe','Asia','North America']
    if 'chessboard' in n: return ['36','48','64','100']
    if 'plural of' in n: return ['criteria','phenomena','analyses','indices','mice','children','geese','oxen']
    if 'which battle' in n: return ['Hastings','Saratoga','Gettysburg','Stalingrad','Verdun','Waterloo','Trafalgar']
    if 'currency of' in n: return ['US dollar','euro','Japanese yen','Indian rupee','pound sterling','Swiss franc']
    if 'largest country' in n: return ['Russia','Canada','China','United States','Brazil']
    if 'smallest country' in n: return ['Vatican City','Monaco','Nauru','Tuvalu','San Marino']
    return []

def build_questions(category,count,seed=None):
    rows=clean_rows(category)
    if len(rows)<4: rows=QUESTION_DATA[category][:]
    count=max(1,min(int(count),len(rows)))
    rng=random.Random(seed if seed is not None else secrets.randbits(64))
    chosen=rng.sample(rows,count)
    result=[]; used_sets=set(); usage={}
    for idx,(q,a) in enumerate(chosen):
        candidates=[]
        qfam=family(q)
        same_family=[(cq,ca) for cq,ca in rows if ca!=a and family(cq)==qfam and compatible_answer(q,ca)]
        source_rows=same_family if len(same_family)>=3 else [(cq,ca) for cq,ca in rows if ca!=a and compatible_answer(q,ca)]
        for cq,ca in source_rows:
            sc=similarity(q,a,cq,ca)
            if shape(ca)!=shape(a): sc-=10
            if cue(cq)!=cue(q): sc-=4
            if family(cq)!=family(q): sc-=10
            aw=max(1,len(str(a).split())); cw=max(1,len(str(ca).split()))
            if abs(aw-cw)>=4: sc-=6
            if abs(len(str(a))-len(str(ca)))>70: sc-=4
            if ca in usage:
                sc-=usage[ca]*2.5
                if usage[ca]>=3: sc-=8
            candidates.append((sc,ca))
        candidates.sort(reverse=True)
        pool=[]
        for sc,ca in candidates:
            if ca not in pool: pool.append(ca)
            if len(pool)>=18: break
        if len(pool)<3:
            pool=list(dict.fromkeys(ca for cq,ca in rows if ca!=a and compatible_answer(q,ca)))
        for ca in topic_pool(q,a):
            if ca!=a and ca not in pool: pool.append(ca)
        opts=[a]
        for ca in pool:
            if ca not in opts: opts.append(ca)
            if len(opts)==4: break
        # A deterministic fallback still stays inside this category and answer shape.
        if len(opts)<4:
            for _,ca in candidates:
                if ca not in opts: opts.append(ca)
                if len(opts)==4: break
        if len(opts)<4:
            continue
        rng.shuffle(opts)
        key=tuple(sorted(norm(x) for x in opts))
        if key in used_sets:
            # choose a different third/fourth distractor where possible
            alt=pool[3:]
            for ca in alt:
                if ca not in opts:
                    opts[-1]=ca; key=tuple(sorted(norm(x) for x in opts))
                    if key not in used_sets: break
        if key in used_sets:
            continue
        used_sets.add(key)
        for o in opts[1:]: usage[o]=usage.get(o,0)+1
        result.append({'question':q,'answer':a,'options':opts,'difficulty':['Easy','Medium','Hard'][idx*3//max(1,count)]})
    if len(result)<count:
        # Final controlled fill: use validated family/topic distractors and try several unique combinations.
        for q,a in rng.sample(rows,len(rows)):
            if len(result)>=count: break
            if any(x['question']==q for x in result): continue
            pool=[]
            for base in result:
                if family(base['question'])==family(q):
                    for ca in base['options']:
                        if ca!=a and ca not in pool and compatible_answer(q,ca): pool.append(ca)
            for ca in topic_pool(q,a):
                if ca!=a and ca not in pool: pool.append(ca)
            for cq,ca in rows:
                if ca!=a and ca not in pool and compatible_answer(q,ca): pool.append(ca)
            if len(pool)<3: continue
            made=False
            for _ in range(min(80, max(10,len(pool)*4))):
                opts=[a]+rng.sample(pool,3); rng.shuffle(opts); key=tuple(sorted(norm(x) for x in opts))
                if key not in used_sets:
                    used_sets.add(key); result.append({'question':q,'answer':a,'options':opts,'difficulty':'Medium'}); made=True; break
            if not made: continue
    return result

def random_questions(count=10):
    rng=random.Random(); buckets=[c for c in NORMAL_CATEGORIES if c!='Love']
    out=[]
    # one or two questions per normal subject before repeating a category
    while len(out)<count:
        rng.shuffle(buckets)
        for c in buckets:
            out.extend(build_questions(c,1))
            if len(out)>=count: return out[:count]
    return out[:count]

def daily_questions():
    day=time.strftime('%Y-%m-%d',time.gmtime()); seed=int(hashlib.sha256(('quizverse-'+day).encode()).hexdigest()[:12],16)
    return build_questions('History',10,seed)[:10]

# ---------------- Multiplayer ----------------
ROOMS={}; ROOM_LOCK=threading.RLock(); RANK_QUEUE=[]; RANK_WAITERS={}

def new_code():
    alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    while True:
        c=''.join(secrets.choice(alphabet) for _ in range(6))
        if c not in ROOMS:return c

def public_question(q): return {'question':q['question'],'options':q['options'],'difficulty':q['difficulty']}

def room_public(r,token=None):
    players=list(r['players'].values()); me=r['players'].get(token); opp=next((x for x in players if not token or x['token']!=token),None); idx=r['index']; q=r['questions'][idx] if idx<len(r['questions']) else None
    review=r['status']=='review'
    return {'code':r['code'],'status':r['status'],'category':r['category'],'mode':r['mode'],'count':len(r['questions']),'index':idx,'time_limit':r['time_limit'],'round_left':max(0,int(r['time_limit']-(time.time()-r['round_started']))) if r['status']=='playing' else 0,
      'review_left':max(0,int(REVIEW_SECONDS-(time.time()-r.get('review_started',0)))) if review else 0,
      'me':({'name':me['name'],'score':me['score'],'answered':me['answered'].get(idx),'correct':me.get('results',{}).get(idx),'response_time':me.get('times',{}).get(idx)} if me else None),
      'opponent':({'name':opp['name'],'score':opp['score'],'answered':(idx in opp['answered']),'correct':opp.get('results',{}).get(idx),'response_time':opp.get('times',{}).get(idx)} if opp else None),
      'players':[{'name':x['name'],'score':x['score']} for x in players],
      'question':public_question(q) if q and r['status'] in ('playing','review') else None,
      'correct_answer':q['answer'] if q and review else None,
      'explanation':explain(q) if q and review else None,
      'winner':r.get('winner'),'finished_scores':r.get('finished_scores'),'ranked_delta':r.get('ranked_delta',{})}

def explain(q):
    return f"The correct answer is {q['answer']}. Compare it with the wording of the question and the other choices."

def finish_room(r):
    players=list(r['players'].values()); vals=[p['score'] for p in players]
    r['finished_scores']={p['name']:p['score'] for p in players}; r['winner']='Tie' if vals[0]==vals[1] else (players[0]['name'] if vals[0]>vals[1] else players[1]['name'])
    if r['mode']=='Ranked':
        delta={}
        if r['winner']=='Tie':
            for p in players: delta[p['name']]=0; update_stats(p['name'],0,len(r['questions']),sum(p.get('times',{}).values()),min(p.get('times',{}).values()) if p.get('times') else 0,draw=1)
        else:
            for p in players:
                won=p['name']==r['winner']; pts=p['score'] if won else 0; delta[p['name']]=pts
                update_stats(p['name'],sum(1 for x in p.get('results',{}).values() if x),len(p.get('results',{})),sum(p.get('times',{}).values()),min(p.get('times',{}).values()) if p.get('times') else 0,win=int(won),loss=int(not won),ranked_delta=pts)
        r['ranked_delta']=delta
    else:
        for p in players:
            win=int(p['name']==r['winner']); loss=int(r['winner']!='Tie' and p['name']!=r['winner']); draw=int(r['winner']=='Tie')
            update_stats(p['name'],sum(1 for x in p.get('results',{}).values() if x),len(p.get('results',{})),sum(p.get('times',{}).values()),min(p.get('times',{}).values()) if p.get('times') else 0,win,loss,draw)
    con=db(); con.execute('INSERT INTO multiplayer_matches(room_code,player1,player2,category,mode,score1,score2,winner) VALUES(?,?,?,?,?,?,?,?)',
      (r['code'],players[0]['name'],players[1]['name'],r['category'],r['mode'],players[0]['score'],players[1]['score'],r['winner'])); con.commit(); con.close(); check_achievements(players[0]['name']); check_achievements(players[1]['name'])

def advance_room(r):
    if r['status']!='playing': return
    players=list(r['players'].values()); idx=r['index']; now=time.time(); all_answered=len(players)==2 and all(idx in p['answered'] for p in players); timeout=now-r['round_started']>=r['time_limit']
    if not (all_answered or timeout): return
    if idx+1>=len(r['questions']): r['status']='review'; r['review_started']=time.time(); return
    r['status']='review'; r['review_started']=time.time()

def advance_review(r):
    if r['status']!='review': return
    if time.time()-r.get('review_started',0)<REVIEW_SECONDS:return
    if r['index']+1>=len(r['questions']): r['status']='finished'; finish_room(r); return
    r['index']+=1; r['round_started']=time.time(); r['status']='playing'

def create_room(name,category,count,seconds,mode='VS Friend',questions=None):
    token=secrets.token_urlsafe(18); code=new_code(); qs=questions or build_questions(category,count)
    r={'code':code,'created':time.time(),'category':category,'mode':mode,'time_limit':seconds,'questions':qs,'index':0,'round_started':0,'status':'waiting','players':{token:{'token':token,'name':safe_name(name),'score':0,'answered':{},'results':{},'times':{}}}}
    ROOMS[code]=r; return r,token

def join_room_obj(r,name):
    token=secrets.token_urlsafe(18); r['players'][token]={'token':token,'name':safe_name(name),'score':0,'answered':{},'results':{},'times':{}}; r['status']='playing'; r['round_started']=time.time(); return token

def cleanup_rooms():
    while True:
        time.sleep(30)
        with ROOM_LOCK:
            cutoff=time.time()-ROOM_TTL
            for c in list(ROOMS):
                if ROOMS[c].get('created',0)<cutoff: ROOMS.pop(c,None)

