SOLOS={}; SOLO_LOCK=threading.RLock()
def solo_view(s,include_answers=False):
    return {'id':s['id'],'name':s['name'],'category':s['category'],'mode':s['mode'],'questions':[public_question(q) for q in s['questions']],
      'answers':s['answers'],'index':s['index'],'score':s.get('score',0),'elapsed':time.time()-s['started'],'results':s.get('results') if include_answers else None}

def safe_name(x):
    x=str(x or 'Player').strip()[:24]; return x or 'Player'
def safe_count(x):
    try:n=int(x)
    except:n=10
    return max(1,min(100,n))

