    init_db(); threading.Thread(target=cleanup_rooms,daemon=True).start(); print('🌐 QuizVerse 2.0 is online!'); print(f'📱 Open http://127.0.0.1:{PORT}'); print('Press Ctrl+C to stop.'); ThreadingHTTPServer((HOST,PORT),Handler).serve_forever()

